def _verify_row(connection, row, values):
    if connection.execute(_ROW_MATCHES[row.table], values).fetchone()[0] != 1:
        raise ValueError("mobile_native_row_changed")


def _prepare_rows(plan, budget):
    """Schedule actual fixed projections against their authenticated native FKs."""
    from .mobile_plan_manifest import _TABLES

    budget.container(len(_TABLES) * 2 + len(plan.rows) * 8)
    specs = {s.table: s for s in _TABLES}
    rows, by_table = [], {}
    for row in plan.rows:
        budget.container(len(row.values) * 2 + 4)
        values = dict(row.values)
        spec = specs[row.table]
        if row.table not in _ROW_INSERTS or row.pending_columns:
            raise ValueError("mobile_native_row_writer_missing")
        if set(values) != set(spec.columns):
            raise ValueError("mobile_native_row_projection_changed")
        index = len(rows)
        rows.append((row, values))
        by_table.setdefault(row.table, []).append(index)
    budget.container(len(rows) * 3)
    edges = [set() for _ in rows]
    for table, indices in by_table.items():
        for index in indices:
            values = rows[index][1]
            for target, source_columns, columns in _ROW_FKS.get(table, ()):
                budget.container(len(columns) * 2)
                expected = tuple(values[column] for column in source_columns)
                if any(value is None for value in expected):
                    continue
                if any(column is None for column in columns):
                    columns = specs[target].identity_columns
                for candidate in by_table.get(target, ()):
                    if candidate != index and all(
                        rows[candidate][1][column] == value
                        for column, value in zip(columns, expected, strict=True)
                    ):
                        budget.container(1)
                        edges[index].add(candidate)
    # Triggers add order constraints beyond declared foreign keys.
    segments = {
        rows[i][1]["segment_id"]: i for i in by_table.get("console_trace_segments", ())
    }
    owners = {
        rows[i][1]["root_segment_id"]: i
        for i in by_table.get("console_trace_owners", ())
    }
    for index, (row, values) in enumerate(rows):
        if row.table in {
            "console_trace_surface_nodes",
            "console_trace_surface_replacements",
            "console_trace_calls",
            "console_trace_events",
            "console_trace_segments",
        }:
            segment = values.get("segment_id")
            if row.table == "console_trace_segments":
                segment = values["parent_segment_id"]
            seen = set()
            while segment is not None:
                if segment in seen:
                    raise ValueError("mobile_native_trace_lineage_cycle")
                budget.container(2)
                seen.add(segment)
                if segment in owners:
                    edges[index].add(owners[segment])
                    break
                segment = rows[segments[segment]][1]["parent_segment_id"]
        if row.table == "console_trace_events" and values["sequence"]:
            for candidate in by_table[row.table]:
                previous = rows[candidate][1]
                if (
                    previous["segment_id"] == values["segment_id"]
                    and previous["sequence"] == values["sequence"] - 1
                ):
                    budget.container(1)
                    edges[index].add(candidate)
    budget.container(len(rows) * 4)
    remaining, emitted, ordered = set(range(len(rows))), set(), []
    while remaining:
        ready = [index for index in remaining if edges[index] <= emitted]
        budget.container(len(ready))
        if not ready:
            raise ValueError("mobile_native_row_lifecycle_cycle")
        for index in ready:
            ordered.append(rows[index])
            emitted.add(index)
            remaining.remove(index)
    budget.container(len(ordered))
    return tuple(ordered)


def _insert_row(connection, row, values):
    """Execute the fixed row's legal insertion, without changing its native clock."""
    if row.table == "conversation_dictionary_attachments":
        saved = connection.execute(
            "SELECT conversation_id,dictionary_id FROM conversation_dictionary_attachments WHERE conversation_id=:conversation_id AND dictionary_id=:dictionary_id",
            values,
        ).fetchone()
        if saved is None or tuple(saved) != (
            values["conversation_id"],
            values["dictionary_id"],
        ):
            raise ValueError("mobile_native_dictionary_derivation_changed")
    elif row.table == "conversation_dictionary_unresolved":
        saved = connection.execute(
            "SELECT conversation_id FROM conversation_dictionary_unresolved WHERE conversation_id=:conversation_id",
            values,
        ).fetchone()
        if saved is None or saved[0] != values["conversation_id"]:
            raise ValueError("mobile_native_dictionary_derivation_changed")
    elif row.table == "agent_runs":
        connection.execute(
            "INSERT INTO agent_runs (id,conversation_id,parent_run_id,agent_kind,task,status,steps,result,budget,created_at,updated_at,assistant_message_id,agent_definition,definition_fingerprint,wake_delivered_at,resumed_from_run_id,spawn_event_id,budget_tokens,resolved_provider,resolved_model,resolved_base_url,resolved_params_json,fallback_targets_json,active_fallback_index,work_chain_id) VALUES (:id,:conversation_id,:parent_run_id,:agent_kind,:task,'running',:steps,NULL,:budget,:created_at,:created_at,:assistant_message_id,:agent_definition,:definition_fingerprint,NULL,:resumed_from_run_id,:spawn_event_id,NULL,:resolved_provider,:resolved_model,:resolved_base_url,:resolved_params_json,:fallback_targets_json,:active_fallback_index,:work_chain_id)",
            values,
        )
        connection.execute(
            "UPDATE agent_runs SET status=:status,result=:result,updated_at=:updated_at,wake_delivered_at=:wake_delivered_at,budget_tokens=:budget_tokens WHERE id=:id AND status='running'",
            values,
        )
    elif row.table == "console_trace_calls":
        _insert_call(connection, values)
    else:
        connection.execute(_ROW_INSERTS[row.table], values)


def _insert_call(connection, values):
    """Replay reservation and observed transitions with their exact stored clocks."""
    connection.execute(
        "INSERT INTO console_trace_calls (call_id,owner_id,segment_id,turn_id,run_id,call_sequence,idempotency_key,policy_id,state,created_at,reservation_provenance,import_reason_code) VALUES (:call_id,:owner_id,:segment_id,:turn_id,:run_id,:call_sequence,:idempotency_key,:policy_id,'reserved',:created_at,:reservation_provenance,:import_reason_code)",
        values,
    )
    state = values["state"]
    if state not in {"reserved", "not_dispatched"}:
        connection.execute(
            "UPDATE console_trace_calls SET state='dispatch_started',surface_node_id=:surface_node_id,request_header_id=:request_header_id,provider_name=:provider_name,model_name=:model_name,route_identity=:route_identity,dispatch_started_at=:dispatch_started_at WHERE call_id=:call_id",
            values,
        )
        if values["response_started_at"] is not None:
            connection.execute(
                "UPDATE console_trace_calls SET state='response_started',response_started_at=:response_started_at WHERE call_id=:call_id",
                values,
            )
    connection.execute(
        "UPDATE console_trace_calls SET state=:state,surface_node_id=:surface_node_id,request_header_id=:request_header_id,provider_name=:provider_name,model_name=:model_name,route_identity=:route_identity,dispatch_started_at=:dispatch_started_at,response_started_at=:response_started_at,settled_at=:settled_at,provider_inactive_at=:provider_inactive_at,outcome=:outcome,usage_json=:usage_json,integrity_state=:integrity_state,omission_reason_code=:omission_reason_code WHERE call_id=:call_id",
        values,
    )


def _advance_snapshot_allocator(connection, allocator):
    """Reserve pruned locators without manufacturing snapshot history."""
    if not connection.in_transaction:
        raise ValueError("mobile_snapshot_owner_transaction_required")
    frontier = allocator.required_frontier
    if type(frontier) is not int or not 0 <= frontier < 2**63 - 1:
        raise ValueError("mobile_snapshot_allocator_exhausted")
    current = connection.execute(
        "SELECT seq FROM sqlite_sequence WHERE name='change_snapshots'"
    ).fetchone()
    if current is None:
        connection.execute(
            "INSERT INTO sqlite_sequence(name,seq) VALUES ('change_snapshots',?)",
            (frontier,),
        )
    elif current[0] < frontier:
        connection.execute(
            "UPDATE sqlite_sequence SET seq=? WHERE name='change_snapshots'",
            (frontier,),
        )
